@import 'c/ihStyles';

:host {
    display: block;
}
.facts {
    display: grid;
    grid-template-columns: max-content 1fr;
    gap: 4px 16px;
    margin: 4px 0 8px;
}
.facts dt {
    color: var(--ih-ink-2);
}
.facts dd {
    margin: 0;
    overflow-wrap: anywhere;
}
.sub {
    margin: 12px 0 4px;
    font-weight: 600;
}
.action {
    display: inline-block;
    margin: 8px 0 4px;
}
.note {
    margin-top: 12px;
}
.job-head {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}
.job-head .sub {
    display: flex;
    align-items: center;
    gap: 6px;
}
.gap {
    margin-top: 16px;
    padding-top: 12px;
    border-top: 1px solid var(--ih-line);
}
.sub_small {
    font-size: 0.8125rem;
}
